/**
 * Workers treat every named export of the entry module as a handler.
 * Nitro's bundle exports app symbols too, so the entry must re-export
 * only the default fetch handler, plus the Durable Object classes that
 * wrangler.toml binds (#35: ChatBudget).
 */
import { copyFileSync, writeFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import { pathToFileURL } from "node:url";
import { buildOutput } from "./build-output.mjs";

export const BUDGET_MODULE = "chat-budget-do.mjs";

export function entrySource(serverEntry) {
  return [
    "// Generated by scripts/write-cf-entry.mjs. Do not edit.",
    'import { DurableObject } from "cloudflare:workers";',
    `import { makeChatBudget } from "./${BUDGET_MODULE}";`,
    `export { default } from "./${basename(serverEntry)}";`,
    "export const ChatBudget = makeChatBudget(DurableObject);",
    "",
  ].join("\n");
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  const { serverEntry, workerEntry } = buildOutput("cloudflare-module");
  const entry = join(process.cwd(), workerEntry);
  // no_bundle: wrangler uploads every .mjs next to the entry as a module.
  copyFileSync(join(process.cwd(), "src/lib/chat-budget.mjs"), join(dirname(entry), BUDGET_MODULE));
  writeFileSync(entry, entrySource(serverEntry));
  console.log("[build:cf] wrote", entry);
}
